// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    X_WALLET c;
    function setUp() public { c = new X_WALLET(address(new Log())); }

    function testFuzz_property(address actor, uint256 amount, uint256 unlockParam) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(0) && actor != address(c));
        amount = bound(amount, 0, 10 ether);
        unlockParam = bound(unlockParam, 0, type(uint256).max / 2);
        // pick a current time that may be AFTER the requested unlockParam (past) or before (future)
        uint256 nowT = bound(uint256(keccak256(abi.encodePacked(actor, unlockParam))), 1, 2 ** 200);
        vm.warp(nowT);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(unlockParam);
        (uint256 unlockTime,) = c.Acc(actor);
        assertTrue(unlockTime >= block.timestamp);
    }
}
